function trailCabin(room,pawn){const ex=room.game.extra,events=['forward3','back2','extra','nextCabin','reverse','camp','freeOut','everyone1'];const e=events[Math.floor(Math.random()*events.length)];if(e==='forward3'){trailMoveOne(room,pawn,3);ex.message='Cabin: Shortcut! Move forward 3.'}if(e==='back2'){trailMoveOne(room,pawn,-2);ex.message='Cabin: Mud bog! Back 2.'}if(e==='extra'){ex.extraTurn=true;ex.message='Cabin: Lucky find! Take another turn.'}if(e==='nextCabin'&&pawn.zone==='track'){const a=trailAbs(room,pawn),target=CABINS.find(x=>x>a)??CABINS[0],delta=(target-a+TRAIL_LEN)%TRAIL_LEN;trailMoveOne(room,pawn,delta);ex.message='Cabin: Borrowed quad! Ride to the next Cabin.'}if(e==='reverse'){ex.direction*=-1;ex.message='Cabin: Storm warning! Direction reversed.'}if(e==='camp'){pawn.zone='camp';pawn.dist=0;ex.message='Cabin: Bear on the trail! Back to Camp.'}if(e==='freeOut'){const ids=trailTeamIds(room,pawn.playerId);const q=ids.flatMap(id=>ex.pawns[id]).find(x=>x.zone==='camp');if(q){q.zone='track';q.dist=0}ex.message='Cabin: Camp raid! A teammate marker hits the trail.'}if(e==='everyone1'){for(const arr of Object.values(ex.pawns))for(const q of arr)if(q.zone==='track')trailMoveOne(room,q,1);ex.message='Cabin: Trail mix tax! Everybody out moves 1.'}}
function trailWinner(room){const ex=room.game.extra,teams=[...new Set(order(room).map(id=>trailTeam(room,id)))];return teams.find(t=>order(room).filter(id=>trailTeam(room,id)===t).flatMap(id=>ex.pawns[id]).every(q=>q.zone==='home'&&q.home===3))||null}
function trailOptions(room,p){const ex=room.game.extra,c=ex.drawn;if(!c)return[];const teamPawns=trailTeamIds(room,p.id).flatMap(id=>ex.pawns[id]);const out=[];if(c.kind==='out'||(c.kind==='move'&&c.value===2)){for(const q of teamPawns.filter(x=>x.zone==='camp'))out.push({action:'trailMove',label:`Hit the Trail with ${P(room,q.playerId).name}'s marker`,args:{pawnId:q.id,mode:'out'}})}if(c.kind==='send'){for(const q of teamPawns.filter(x=>x.zone==='camp'))for(const [oid,arr] of Object.entries(ex.pawns))if(trailTeam(room,oid)!==trailTeam(room,p.id))for(const target of arr.filter(x=>x.zone==='track'))out.push({action:'trailMove',label:`SEND PACKING: replace ${P(room,oid).name}'s marker`,args:{pawnId:q.id,targetPawnId:target.id,mode:'send'}})}if(c.kind==='move'){const vals=c.value===4?[-4]:c.value===10?[10,-1]:[c.value];for(const q of teamPawns.filter(x=>x.zone!=='camp'))for(const v of vals){const cp={...q};if(trailMoveOne(room,cp,v))out.push({action:'trailMove',label:`Move ${P(room,q.playerId).name}'s marker ${v>0?'+':''}${v}`,args:{pawnId:q.id,steps:v}})}if(c.value===7){for(const a of teamPawns.filter(x=>x.zone!=='camp'))for(const b of teamPawns.filter(x=>x.zone!=='camp'&&x.id!==a.id))for(const x of [1,2,3]){const ac={...a},bc={...b};if(trailMoveOne(room,ac,x)&&trailMoveOne(room,bc,7-x))out.push({action:'trailSplit',label:`Split 7: ${x} + ${7-x}`,args:{a:a.id,b:b.id,x,y:7-x}})}}if(c.value===11){for(const q of teamPawns.filter(x=>x.zone==='track'))for(const [oid,arr] of Object.entries(ex.pawns))if(trailTeam(room,oid)!==trailTeam(room,p.id))for(const target of arr.filter(x=>x.zone==='track'))out.push({action:'trailSwap',label:`Trade places with ${P(room,oid).name}`,args:{a:q.id,b:target.id}})}}if(c.kind==='cabin'){for(const q of teamPawns.filter(x=>x.zone==='track'))out.push({action:'trailCabin',label:`Send a marker to a random cabin event`,args:{pawnId:q.id}})}return out.slice(0,150)}
function trailPublic(room,viewer){const ex=room.game.extra,actions=[];if(viewer&&ex.turnPlayerId===viewer.id){if(!ex.drawn)actions.push({action:'trailDraw',label:'Draw Trail card'});else{actions.push(...trailOptions(room,viewer));if(!trailOptions(room,viewer).length)actions.push({action:'trailDiscard',label:`No legal move · discard ${ex.drawn.label}`})}}return {type:ex.type,phase:ex.phase,turnPlayerId:ex.turnPlayerId,drawn:ex.drawn,deckCount:ex.deck.length,discardTop:ex.discard.at(-1)||null,direction:ex.direction,trackLength:TRAIL_LEN,startPositions:Object.fromEntries(order(room).map(id=>[id,trailStartPos(room,id)])),pawns:ex.pawns,cabins:ex.cabins,message:ex.message,teamMode:room.settings.teamMode,teams:Object.fromEntries(order(room).map(id=>[id,trailTeam(room,id)])),actions};}
function trailEndTurn(room,p,extra=false){const ex=room.game.extra,w=trailWinner(room);if(w){finishGame(room,order(room).filter(id=>trailTeam(room,id)===w),'All team markers made it Home.');return}const again=extra||ex.extraTurn;ex.extraTurn=false;ex.drawn=null;if(!again)ex.turnPlayerId=next(room,p.id,ex.direction)}

// ---------------- MARBLES & JOKERS ----------------
function marbleTeam(room,id){const ids=order(room),i=ids.indexOf(id),mode=room.settings.teamMode;if(mode==='solo'||ids.length%2===1)return id;return i%2===0?'A':'B'}
function marbleDeck(n){return shuffle(standardDeck({decks:n>=8?4:3,jokers:n>=8?8:6}))}
function marblesStart(room){resetPlayerRound(room);const ids=order(room),deck=marbleDeck(ids.length),pawns={};for(const id of ids){P(room,id).hand=[];for(let i=0;i<5;i++)P(room,id).hand.push(deck.pop());pawns[id]=Array.from({length:5},()=>({id:gid('m'),playerId:id,zone:'start',dist:0,home:0}))}setExtra(room,{type:GAME_TYPES.MARBLES,phase:'playing',stock:deck,discard:[],turnPlayerId:ids[0],pawns,message:'Draw, play a card, then move a marble.',history:[]})}
function marbleTrackLen(room){return order(room).length*18}
function marbleStartPos(room,id){return order(room).indexOf(id)*18+8}
function marbleInPos(room,id){return order(room).indexOf(id)*18+3}
function marbleNorm(room,n){const len=marbleTrackLen(room);return((n%len)+len)%len}
function marbleEntryDist(room,id){return marbleNorm(room,marbleInPos(room,id)-marbleStartPos(room,id))}
function marbleAbs(room,q){return marbleNorm(room,marbleStartPos(room,q.playerId)+(q.dist||0))}
function marbleTeamIds(room,id){const t=marbleTeam(room,id);return order(room).filter(x=>marbleTeam(room,x)===t)}
function marbleOwnPawns(room,id){return room.game.extra.pawns[id]||[]}
function marbleAllowedIds(room,id){return marbleOwnPawns(room,id).every(q=>q.zone==='home')?marbleTeamIds(room,id):[id]}
function marbleTrackAt(room,abs,excludeId=null){const ex=room.game.extra,a=marbleNorm(room,abs),out=[];for(const arr of Object.values(ex.pawns))for(const q of arr)if(q.id!==excludeId&&q.zone==='track'&&marbleAbs(room,q)===a)out.push(q);return out}
function marbleSameColorBlocksTrack(room,q,steps){if(q.zone!=='track')return false;const dir=steps>=0?1:-1;for(let k=1;k<=Math.abs(steps);k++){const a=marbleNorm(room,marbleAbs(room,q)+dir*k);if(marbleTrackAt(room,a,q.id).some(z=>z.playerId===q.playerId))return true}return false}
function marbleHomePathClear(room,q,from,to){return !marbleOwnPawns(room,q.playerId).some(z=>z.id!==q.id&&z.zone==='home'&&z.home>from&&z.home<=to)}
function marbleCanPlaceAtInSpot(room,q,seen=new Set()){if(seen.has(q.id))return false;const nextSeen=new Set(seen);nextSeen.add(q.id);const ownIn=marbleInPos(room,q.playerId),occupants=marbleTrackAt(room,ownIn,q.id);if(occupants.some(z=>z.playerId===q.playerId))return false;for(const z of occupants)if(marbleTeam(room,z.playerId)===marbleTeam(room,q.playerId)&&!marbleCanPlaceAtInSpot(room,z,nextSeen))return false;return true}
function marblePartnerLandingPossible(room,q,target){if(!target||target.playerId===q.playerId)return false;if(marbleTeam(room,target.playerId)!==marbleTeam(room,q.playerId))return true;return marbleCanPlaceAtInSpot(room,target)}
function marbleTrackLandingPossible(room,q,abs){const occupants=marbleTrackAt(room,abs,q.id);if(occupants.some(z=>z.playerId===q.playerId))return false;return occupants.every(z=>marblePartnerLandingPossible(room,q,z))}
function marbleSingleMoves(room,q,steps){const out=[];if(q.zone==='start')return out;if(q.zone==='home'){if(steps<=0)return out;const to=q.home+steps;if(to<=5&&marbleHomePathClear(room,q,q.home,to))out.push({route:'home',home:to});return out}
 if(q.zone!=='track')return out;
 // Backward moves remain on the main track and can never back into Home.
 if(steps<0){if(!marbleSameColorBlocksTrack(room,q,steps)){const abs=marbleNorm(room,marbleAbs(room,q)+steps);if(marbleTrackLandingPossible(room,q,abs))out.push({route:'track',dist:marbleNorm(room,(q.dist||0)+steps)})}return out}
 // Continuing around the main track is always an option if the path is clear.
 if(!marbleSameColorBlocksTrack(room,q,steps)){const abs=marbleNorm(room,marbleAbs(room,q)+steps);if(marbleTrackLandingPossible(room,q,abs))out.push({route:'track',dist:marbleNorm(room,(q.dist||0)+steps)})}
 // A forward move may branch into the player's own five-hole Home track after passing the in-spot.
 const entry=marbleEntryDist(room,q.playerId),dist=marbleNorm(room,q.dist||0),toEntry=marbleNorm(room,entry-dist);if(steps>toEntry){const h=steps-toEntry;if(h>=1&&h<=5&&marbleHomePathClear(room,q,0,h)){let blocked=false;for(let k=1;k<=toEntry;k++){const a=marbleNorm(room,marbleAbs(room,q)+k);if(marbleTrackAt(room,a,q.id).some(z=>z.playerId===q.playerId)){blocked=true;break}}if(!blocked)out.push({route:'home',home:h})}}
 return out}
function marblePlaceAtInSpot(room,q,seen=new Set()){const key=q.id;if(seen.has(key))return;seen.add(key);const abs=marbleInPos(room,q.playerId),occupants=marbleTrackAt(room,abs,q.id);if(occupants.some(z=>z.playerId===q.playerId))throw new Error('Partner in-spot is blocked');q.zone='track';q.home=0;q.dist=marbleEntryDist(room,q.playerId);for(const z of occupants){if(z.playerId===q.playerId)continue;if(marbleTeam(room,z.playerId)===marbleTeam(room,q.playerId))marblePlaceAtInSpot(room,z,seen);else{z.zone='start';z.dist=0;z.home=0}}}
function marbleResolveLanding(room,q){if(q.zone!=='track')return;const occupants=marbleTrackAt(room,marbleAbs(room,q),q.id);for(const z of occupants){if(z.playerId===q.playerId)throw new Error('Cannot land on your own marble');if(marbleTeam(room,z.playerId)===marbleTeam(room,q.playerId))marblePlaceAtInSpot(room,z);else{z.zone='start';z.dist=0;z.home=0}}}
function marbleApplySingle(room,q,steps,route){const opts=marbleSingleMoves(room,q,steps),chosen=opts.find(x=>x.route===route);if(!chosen)throw new Error('Illegal marble move');if(route==='home'){q.zone='home';q.home=chosen.home;q.dist=0}else{q.zone='track';q.dist=chosen.dist;q.home=0;marbleResolveLanding(room,q)}}
function marbleOutLegal(room,q){if(q.zone!=='start')return false;const abs=marbleStartPos(room,q.playerId);return marbleTrackLandingPossible(room,q,abs)}
function marbleApplyOut(room,q){if(!marbleOutLegal(room,q))throw new Error('Come-out space is blocked');q.zone='track';q.dist=0;q.home=0;marbleResolveLanding(room,q)}
function marbleJokerLegal(room,q,target){if(!q||!target||q.id===target.id||target.zone!=='track'||q.zone==='home'||target.playerId===q.playerId)return false;return marblePartnerLandingPossible(room,q,target)}
function marbleApplyJoker(room,q,target){if(!marbleJokerLegal(room,q,target))throw new Error('Invalid Joker move');q.zone='track';q.home=0;q.dist=marbleNorm(room,marbleAbs(room,target)-marbleStartPos(room,q.playerId));marbleResolveLanding(room,q)}
function marbleOptions(room,p,c){const ex=room.game.extra,allowed=new Set(marbleAllowedIds(room,p.id)),own=[...allowed].flatMap(id=>ex.pawns[id]),out=[],exit=['A','J','Q','K'].includes(c.rank);if(exit)for(const q of own.filter(x=>x.zone==='start'&&marbleOutLegal(room,x)))out.push({action:'marbleMove',label:`Bring out ${P(room,q.playerId).name}'s marble`,args:{pawnId:q.id,mode:'out'}});if(c.joker){for(const q of own.filter(x=>x.zone!=='home'))for(const arr of Object.values(ex.pawns))for(const t of arr.filter(x=>x.zone==='track'&&x.playerId!==q.playerId))if(marbleJokerLegal(room,q,t))out.push({action:'marbleMove',label:`Joker onto ${P(room,t.playerId).name}'s marble`,args:{pawnId:q.id,targetPawnId:t.id,mode:'joker'}});return out.slice(0,120)}let vals=[];if(c.rank==='A')vals=[1];else if(['J','Q','K'].includes(c.rank))vals=[10];else if(c.rank==='8')vals=[-8];else vals=[Number(c.rank)||0];for(const q of own.filter(x=>x.zone!=='start'))for(const v of vals)for(const m of marbleSingleMoves(room,q,v))out.push({action:'marbleMove',label:`Move ${P(room,q.playerId).name} ${v>0?'+':''}${v}${m.route==='home'?' into Home':''}`,args:{pawnId:q.id,steps:v,route:m.route}});if(c.rank==='7'){for(const a of own.filter(x=>x.zone!=='start'))for(const b of own.filter(x=>x.zone!=='start'&&x.id!==a.id))for(const x of [1,2,3])for(const ma of marbleSingleMoves(room,a,x))for(const mb of marbleSingleMoves(room,b,7-x))out.push({action:'marbleSplit',label:`Split 7: ${x} + ${7-x}`,args:{a:a.id,b:b.id,x,y:7-x,routeA:ma.route,routeB:mb.route}})}return out.slice(0,180)}
function marblesPublic(room,viewer){const ex=room.game.extra,actions=[];if(viewer&&ex.turnPlayerId===viewer.id){if(!ex.drawn)actions.push({action:'marbleDraw',label:'Draw a card'});else{for(const c of viewer.hand)for(const o of marbleOptions(room,viewer,c))actions.push({...o,args:{...o.args,cardId:c.id},label:`${c.joker?'Joker':c.rank}: ${o.label}`});if(!actions.length)actions.push({action:'marbleDiscard',label:'Discard · no legal move'})}}return {type:ex.type,phase:ex.phase,turnPlayerId:ex.turnPlayerId,drawn:!!ex.drawn,stockCount:ex.stock.length,discardTop:cloneCard(ex.discard.at(-1)),pawns:ex.pawns,teams:Object.fromEntries(order(room).map(id=>[id,marbleTeam(room,id)])),trackLen:marbleTrackLen(room),homeLen:5,hand:viewer?viewer.hand:[],actions};}
function marblesWin(room){const ex=room.game.extra,teams=[...new Set(order(room).map(id=>marbleTeam(room,id)))];return teams.find(t=>order(room).filter(id=>marbleTeam(room,id)===t).flatMap(id=>ex.pawns[id]).every(q=>q.zone==='home'))||null}


// ---------------- POKER HAND HELPERS / PRAIRIE POTS ----------------
function eval5(cards){const vals=cards.map(c=>rankNum(c.rank)).sort((a,b)=>b-a),counts={};for(const v of vals)counts[v]=(counts[v]||0)+1;const groups=Object.entries(counts).map(([v,n])=>({v:+v,n})).sort((a,b)=>b.n-a.n||b.v-a.v),flush=cards.every(c=>c.suit===cards[0].suit),uniq=[...new Set(vals)],wheel=uniq.includes(14)&&[5,4,3,2].every(v=>uniq.includes(v));let straightHigh=wheel?5:0;for(let i=0;i<=uniq.length-5;i++){const sl=uniq.slice(i,i+5);if(sl[0]-sl[4]===4)straightHigh=Math.max(straightHigh,sl[0])}const kick=arr=>arr;
 if(flush&&straightHigh)return{cat:8,t:[straightHigh],name:straightHigh===14?'Royal Flush':'Straight Flush'};if(groups[0].n===4)return{cat:7,t:[groups[0].v,...vals.filter(v=>v!==groups[0].v).slice(0,1)],name:'Four of a Kind'};if(groups[0].n===3&&groups[1]?.n>=2)return{cat:6,t:[groups[0].v,groups[1].v],name:'Full House'};if(flush)return{cat:5,t:kick(vals),name:'Flush'};if(straightHigh)return{cat:4,t:[straightHigh],name:'Straight'};if(groups[0].n===3)return{cat:3,t:[groups[0].v,...vals.filter(v=>v!==groups[0].v).slice(0,2)],name:'Three of a Kind'};const pairs=groups.filter(g=>g.n===2);if(pairs.length>=2)return{cat:2,t:[pairs[0].v,pairs[1].v,...vals.filter(v=>v!==pairs[0].v&&v!==pairs[1].v).slice(0,1)],name:'Two Pair'};if(pairs.length===1)return{cat:1,t:[pairs[0].v,...vals.filter(v=>v!==pairs[0].v).slice(0,3)],name:'Pair'};return{cat:0,t:vals,name:'High Card'}}
function cmpEval(a,b){if(a.cat!==b.cat)return a.cat-b.cat;for(let i=0;i<Math.max(a.t.length,b.t.length);i++){const d=(a.t[i]||0)-(b.t[i]||0);if(d)return d}return 0}
function bestPoker(cards){let best=null,bestCards=null;for(const c of combinations(cards,5)){const e=eval5(c);if(!best||cmpEval(e,best)>0){best=e;bestCards=c}}return{...best,cards:bestCards||[]}}
const PRAIRIE_POTS=['poker','black10','diamondJ','clubQ','heartK','blackA','diamondRoyal','luckyRun','prairie'];
function prairieDeal(room,keep=false){resetPlayerRound(room);const ids=order(room),ex0=room.game.extra||{},round=(ex0.round||0)+1,pots=ex0.pots||Object.fromEntries(PRAIRIE_POTS.map(k=>[k,0]));if(!keep)for(const id of ids)P(room,id).score=room.settings.startingChips;for(const id of ids)for(const k of PRAIRIE_POTS){if(P(room,id).score>0){P(room,id).score--;pots[k]++}}const deck=shuffle(standardDeck()),handN=Math.floor(deck.length/(ids.length+1));for(let i=0;i<handN;i++)for(const id of ids)P(room,id).hand.push(deck.pop());const widow=[];while(deck.length)widow.push(deck.pop());const pokerRanks=ids.map(id=>({id,e:bestPoker(P(room,id).hand)})),best=pokerRanks.reduce((a,b)=>cmpEval(b.e,a.e)>0?b:a),ties=pokerRanks.filter(x=>cmpEval(x.e,best.e)===0);if(pots.poker){const share=Math.floor(pots.poker/ties.length);for(const x of ties)P(room,x.id).score+=share;pots.poker-=share*ties.length}const dealer=ex0.dealerId?next(room,ex0.dealerId):ids[Math.floor(Math.random()*ids.length)],starter=next(room,dealer);setExtra(room,{type:GAME_TYPES.PRAIRIE,phase:'sequence',round,roundCount:room.settings.roundCount,dealerId:dealer,turnPlayerId:starter,stock:[],widow,pots,required:null,lastPlayerId:null,playedBy:Object.fromEntries(ids.map(id=>[id,[]])),pokerWinnerIds:ties.map(x=>x.id),pokerName:best.e.name,history:ex0.history||[],continued:[]});}
function prairiePayCard(ex,p,c){const keys=[];if(c.rank==='10'&&c.suit==='spades')keys.push('black10');if(c.rank==='J'&&c.suit==='diamonds')keys.push('diamondJ');if(c.rank==='Q'&&c.suit==='clubs')keys.push('clubQ');if(c.rank==='K'&&c.suit==='hearts')keys.push('heartK');if(c.rank==='A'&&c.suit==='spades')keys.push('blackA');const played=ex.playedBy[p.id];if(c.suit==='diamonds'&&['K','A'].includes(c.rank)&&['K','A'].every(r=>played.some(x=>x.suit==='diamonds'&&x.rank===r)))keys.push('diamondRoyal');for(const s of SUITS)if(['7','8','9'].every(r=>played.some(x=>x.suit===s&&x.rank===r)))keys.push('luckyRun');for(const k of new Set(keys))if(ex.pots[k]>0){p.score+=ex.pots[k];ex.pots[k]=0}}
function prairieFindHolder(room,suit,rank){return order(room).find(id=>P(room,id).hand.some(c=>c.suit===suit&&c.rank===rank))||null}
function prairieNextRank(r){const seq=RANKS;const i=seq.indexOf(r);return i>=0&&i<seq.length-1?seq[i+1]:null}
function prairieLowestOfColor(hand,color){return hand.filter(c=>colorOfSuit(c.suit)===color).sort((a,b)=>lowRankNum(a.rank)-lowRankNum(b.rank))[0]||null}
function prairieAdvance(room,p,c){const ex=room.game.extra,nr=prairieNextRank(c.rank);if(nr){const holder=prairieFindHolder(room,c.suit,nr);if(holder){ex.required={suit:c.suit,rank:nr};ex.turnPlayerId=holder;return}}const opposite=colorOfSuit(c.suit)==='red'?'black':'red';let x=p.id;for(let i=0;i<order(room).length;i++){const cand=P(room,x),lo=prairieLowestOfColor(cand.hand,opposite);if(lo){ex.required=null;ex.turnPlayerId=x;return}x=next(room,x)}ex.required=null;ex.turnPlayerId=next(room,p.id)}
function prairieEndRound(room,winner){const ex=room.game.extra;winner.score+=ex.pots.prairie;ex.pots.prairie=0;for(const id of order(room))if(id!==winner.id){const pay=Math.min(P(room,id).score,P(room,id).hand.length);P(room,id).score-=pay;ex.pots.prairie+=pay}ex.history.push({round:ex.round,winnerId:winner.id,pokerWinnerIds:ex.pokerWinnerIds,pots:{...ex.pots},chips:Object.fromEntries(order(room).map(id=>[id,P(room,id).score]))});if(ex.round>=ex.roundCount){const mx=Math.max(...order(room).map(id=>P(room,id).score));finishGame(room,order(room).filter(id=>P(room,id).score===mx),'Most Prairie Pots chips wins.')}else{ex.phase='roundResults';ex.continued=[]}}
function prairiePublic(room,viewer){const ex=room.game.extra,actions=[];if(viewer&&ex.phase==='sequence'&&ex.turnPlayerId===viewer.id){let legal=[];if(ex.required)legal=viewer.hand.filter(c=>c.suit===ex.required.suit&&c.rank===ex.required.rank);else{const colors=ex.lastPlayerId?[(colorOfSuit(ex.playedBy[ex.lastPlayerId]?.at(-1)?.suit)==='red'?'black':'red')]:['red','black'];for(const col of colors){const lo=prairieLowestOfColor(viewer.hand,col);if(lo)legal.push(lo)}if(!legal.length){for(const s of SUITS){const cand=viewer.hand.filter(c=>c.suit===s).sort((a,b)=>lowRankNum(a.rank)-lowRankNum(b.rank))[0];if(cand)legal.push(cand)}}}for(const c of legal)actions.push({action:'prairiePlay',label:`Play ${c.rank}${c.suit[0].toUpperCase()}`,args:{cardId:c.id}})}if(viewer&&ex.phase==='roundResults'&&!ex.continued.includes(viewer.id))actions.push({action:'prairieContinue',label:'Continue'});return {type:ex.type,phase:ex.phase,round:ex.round,roundCount:ex.roundCount,dealerId:ex.dealerId,turnPlayerId:ex.turnPlayerId,required:ex.required,pots:ex.pots,pokerWinnerIds:ex.pokerWinnerIds,pokerName:ex.pokerName,hand:viewer?viewer.hand:[],widowCount:ex.widow.length,history:ex.history,actions};}

