function havenStart(room){resetPlayerRound(room);const ids=order(room),board=havenBoard(ids.length),resources=Object.fromEntries(ids.map(id=>[id,resBlank()])),survival=Object.fromEntries(ids.map(id=>[id,[]])),hiddenPoints=Object.fromEntries(ids.map(id=>[id,0])),patrolPlayed=Object.fromEntries(ids.map(id=>[id,0]));const ex={type:GAME_TYPES.LAST_HAVEN,phase:'setupCamp',board,camps:{},routes:{},resources,survival,hiddenPoints,patrolPlayed,longestOwner:null,patrolOwner:null,raiderWarnings:0,raiderTile:board.tiles.find(t=>t.resource==='dead')?.id,turnPlayerId:ids[0],setupSequence:[...ids,...ids.slice().reverse()],setupIndex:0,setupCampVertex:null,dice:null,rolled:false,message:'Place your first Camp.',tradeOffer:null,survivalDeck:havenSurvivalDeck(),history:[]};setExtra(room,ex);for(const id of ids)P(room,id).score=0}
